const item = $input.first().json;
const data = item.body?.data || item.data || {};
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const rawMsg = data.message?.conversation 
  || data.message?.extendedTextMessage?.text 
  || '';
const cleanMsg = rawMsg.trim().toLowerCase();
const staticData = $getWorkflowStaticData('global');
const attendedContacts = staticData.attendedContacts || {};

if (!remoteJid) {
  return [];
}

// Permitir que o cliente ou o atendente finalize o atendimento.
if (cleanMsg === 'finalizar') {
  delete attendedContacts[remoteJid];
  staticData.attendedContacts = attendedContacts;
  return [{ json: { telefone: remoteJid, nomeCliente: data.pushName || 'Cliente', mensagemRecebida: rawMsg, routeIndex: 5 } }];
}

// Não interferir enquanto o atendimento humano estiver ativo.
if (attendedContacts[remoteJid]) {
  return [];
}

// Ignorar mensagens enviadas pelo próprio bot ou pelo atendente.
if (key.fromMe === true) {
  return [];
}

// Ignorar grupos e status de stories.
if (remoteJid.includes('@g.us') || remoteJid.includes('status@broadcast')) {
  return [];
}

let routeIndex = 4; // 4 = Menu Principal por padrão

if (cleanMsg === '1' || cleanMsg.includes('plano') || cleanMsg.includes('preço') || cleanMsg.includes('preco')) {
  routeIndex = 0;
} else if (cleanMsg === '3' || cleanMsg.includes('suporte') || cleanMsg.includes('ajuda') || cleanMsg.includes('defeito') || cleanMsg.includes('instala')) {
  routeIndex = 1;
} else if (cleanMsg === '2' || cleanMsg.includes('teste') || cleanMsg.includes('gratis') || cleanMsg.includes('grátis')) {
  routeIndex = 2;
} else if (cleanMsg === '4' || cleanMsg.includes('atendente') || cleanMsg.includes('humano') || cleanMsg.includes('falar')) {
  routeIndex = 3;
}

if (routeIndex === 3) {
  attendedContacts[remoteJid] = true;
  staticData.attendedContacts = attendedContacts;
}

return [{
  json: {
    telefone: remoteJid,
    nomeCliente: data.pushName || 'Cliente',
    mensagemRecebida: rawMsg,
    routeIndex: routeIndex
  }
}];
